-- V147: Офисная Академия — PM-трек (12 уроков, 100+ вопросов)
-- Залы Асгарда: Искусство руководства

-- ═══════════════════════════════════════════════════════════════
-- УРОК 1: Жизненный цикл проекта
-- ═══════════════════════════════════════════════════════════════
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons
  (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (2, 'pm', 'Жизненный цикл проекта — от тендера до закрытия акта', 'Искусство руководства', '⚙️', '#1e2840',
$blocks$[
  {"type":"cover","icon":"⚙️","title":"Жизненный цикл проекта","subtitle":"От первого звонка заказчика до подписания финального акта"},
  {"type":"intro","text":"Каждый проект в Асгарде проходит строго определённый путь — от момента, когда заказчик впервые обращается к нам, до подписания акта выполненных работ. Понимание этого цикла — фундамент работы руководителя проекта. Ошибка на любом этапе может стоить компании миллионы рублей, репутацию и долгосрочные контракты. В этом свитке мы разберём каждый этап детально, с реальными примерами из практики Асгарда на нефтеперерабатывающих заводах."},
  {"type":"text_block","title":"Этап 1: Тендер и предварительная оценка","text":"Всё начинается с тендера. Заказчик — как правило, крупный НПЗ или нефтехимическое предприятие — публикует техническое задание на выполнение работ: химическая промывка теплообменников, нанесение теплоизоляции, монтаж металлоконструкций. РП получает ТЗ через CRM Асгарда и в течение 24 часов должен провести первичную экспертизу. На этом этапе критически важно оценить объём работ, сроки, необходимые допуски и лицензии. Если проект требует работы с опасными химическими реагентами, нужно убедиться в наличии лицензии на обращение с отходами I-IV класса. Асгард имеет собственную лицензию на утилизацию — это наше конкурентное преимущество, которое снижает стоимость проекта на 8-12%."},
  {"type":"icon_grid","title":"Ключевые документы на старте","items":[{"icon":"📋","label":"ТЗ заказчика","desc":"Техническое задание с объёмами, сроками и требованиями к качеству"},{"icon":"💰","label":"КП / Смета","desc":"Коммерческое предложение с расчётом стоимости каждой позиции"},{"icon":"📄","label":"Договор","desc":"Юридическое оформление обязательств сторон и условий оплаты"},{"icon":"👷","label":"ППР","desc":"Проект производства работ — технология, безопасность, графики"},{"icon":"🔒","label":"Допуски и лицензии","desc":"СРО, лицензия на отходы, аттестация НАКС для сварщиков"},{"icon":"📊","label":"График работ","desc":"Детальный план-график с контрольными точками и дедлайнами"}]},
  {"type":"warning","level":"danger","text":"Никогда не начинайте работы без подписанного договора — даже если заказчик «очень просит» и «договор на согласовании». В 2023 году компания потеряла 4,2 млн рублей из-за работ, выполненных без договора: заказчик отказался платить, сославшись на отсутствие юридических оснований. Устные договорённости в суде не работают."},
  {"type":"text_block","title":"Этап 2: Мобилизация и подготовка","text":"После подписания договора начинается мобилизация — один из самых ответственных этапов. РП должен сформировать бригаду нужного состава и квалификации, организовать доставку оборудования и расходных материалов на объект, согласовать с заказчиком пропуска и допуски на территорию. Для работы на НПЗ каждый сотрудник проходит вводный инструктаж заказчика, получает именной пропуск и защитную экипировку. Типичный срок мобилизации — 3-7 рабочих дней в зависимости от удалённости объекта. На объектах Крайнего Севера срок увеличивается до 10-14 дней из-за логистики."},
  {"type":"steps","title":"Алгоритм мобилизации","items":["Сформировать бригаду: определить состав (мастер, рабочие, сварщики), проверить допуски и медосмотры","Заказать оборудование и материалы через отдел закупок — минимум за 5 дней до выезда","Оформить командировочные документы и суточные в бухгалтерии","Согласовать с заказчиком даты заезда, список персонала для пропусков","Организовать транспорт и проживание: авиабилеты/ж/д, гостиница или вахтовый посёлок","Провести предвыездной инструктаж бригады: объект, задачи, особенности, правила ТБ","Проверить наличие всех СИЗ, инструментов и расходных материалов по чек-листу"]},
  {"type":"text_block","title":"Этап 3: Выполнение работ на объекте","text":"На объекте РП контролирует выполнение работ в соответствии с ППР и графиком. Ежедневно проводится планёрка с бригадой, фиксируется объём выполненных работ в журнале, делаются фотоотчёты для заказчика. Критически важно вести исполнительную документацию параллельно с работами — не откладывать на потом. Акты скрытых работ оформляются до того, как следующий слой закроет предыдущий. При химической промывке обязательно фиксируются параметры раствора: концентрация, температура, время экспозиции. Все отклонения от ППР согласовываются с заказчиком письменно через официальные письма или CRM."},
  {"type":"scenario","title":"Заказчик меняет объём работ на ходу","text":"Вы на объекте Газпром нефтехим Салават. По договору — промывка 12 теплообменников. На третий день представитель заказчика просит промыть ещё 4 аппарата «пока вы здесь». Бригада свободна, реагенты есть. Мастер говорит: «Давай сделаем, потом оформим». Как поступить?","resolution":"Правильно: остановиться и оформить дополнительное соглашение к договору ПЕРЕД началом работ. Составить акт дополнительных объёмов, согласовать стоимость, получить письменное подтверждение от уполномоченного лица заказчика (не мастера, а главного инженера или директора). Только после этого приступать. Это займёт 1-2 дня, но защитит от неоплаты 4 дополнительных аппаратов."},
  {"type":"text_block","title":"Этап 4: Приёмка и закрытие","text":"Завершающий этап — приёмка выполненных работ заказчиком. РП готовит полный комплект исполнительной документации: акты выполненных работ по форме КС-2, справки о стоимости по форме КС-3, акты скрытых работ, протоколы испытаний, сертификаты на использованные материалы. Заказчик проводит визуальный осмотр и инструментальный контроль. При обнаружении дефектов составляется дефектная ведомость с указанием сроков устранения. После подписания КС-2 и КС-3 начинается демобилизация — вывоз оборудования, сдача пропусков, уборка рабочей зоны."},
  {"type":"stat","value":"45 дней","label":"средний цикл проекта в Асгарде — от подписания договора до закрытия акта","source":"Аналитика CRM за 2025 год"},
  {"type":"checklist","title":"Чек-лист закрытия проекта","items":["КС-2 и КС-3 подписаны обеими сторонами","Акты скрытых работ оформлены и подписаны","Исполнительная документация передана заказчику","Оборудование вывезено с объекта, площадка убрана","Финальный фотоотчёт загружен в CRM","Отходы утилизированы по лицензии (акт утилизации)","Финансовый отчёт по проекту закрыт в CRM"]},
  {"type":"fact_card","icon":"📊","text":"В 2025 году Асгард выполнил 53 проекта промышленных услуг на общую сумму 847 млн рублей. Средняя маржинальность составила 28,4%. Три проекта были убыточными — во всех трёх случаях причиной стало отсутствие допсоглашений на дополнительные объёмы работ."},
  {"type":"quote","text":"Проект без плана — это просто дорогая импровизация","author":"Том Демарко, «Вальсируя с медведями»"},
  {"type":"highlight","text":"Правило Асгарда: маржинальность проекта должна быть не менее 25%. Если при расчёте сметы маржа ниже — эскалируй на коммерческого директора для принятия решения."},
  {"type":"divider"}
]$blocks$::jsonb,
12, ARRAY['проект','цикл','тендер','КС-2','КС-3','договор'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'На сколько процентов лицензия Асгарда на утилизацию отходов снижает стоимость проекта?',
 '[{"text":"3-5%","is_correct":false},{"text":"8-12%","is_correct":true},{"text":"15-20%","is_correct":false},{"text":"25-30%","is_correct":false}]',
 'Собственная лицензия на утилизацию отходов I-IV класса снижает стоимость проекта на 8-12%, так как не нужно платить сторонним организациям за вывоз и утилизацию.'),
(lid, 2, 'choice', 'Какой минимальный процент маржинальности установлен в Асгарде для проектов?',
 '[{"text":"15%","is_correct":false},{"text":"20%","is_correct":false},{"text":"25%","is_correct":true},{"text":"30%","is_correct":false}]',
 'Правило Асгарда: маржинальность проекта должна быть не менее 25%. При более низкой марже решение принимает коммерческий директор.'),
(lid, 3, 'choice', 'Каков типичный срок мобилизации на объекты Крайнего Севера?',
 '[{"text":"3-5 дней","is_correct":false},{"text":"5-7 дней","is_correct":false},{"text":"10-14 дней","is_correct":true},{"text":"20-30 дней","is_correct":false}]',
 'На объектах Крайнего Севера срок мобилизации увеличивается до 10-14 дней из-за сложной логистики (авиаперелёты, пересадки, вахтовые посёлки).'),
(lid, 4, 'choice', 'Сколько проектов Асгард выполнил в 2025 году?',
 '[{"text":"35","is_correct":false},{"text":"47","is_correct":false},{"text":"53","is_correct":true},{"text":"68","is_correct":false}]',
 'В 2025 году Асгард выполнил 53 проекта промышленных услуг на общую сумму 847 млн рублей.'),
(lid, 5, 'choice', 'Каков средний цикл проекта в Асгарде от подписания договора до закрытия акта?',
 '[{"text":"20 дней","is_correct":false},{"text":"30 дней","is_correct":false},{"text":"45 дней","is_correct":true},{"text":"60 дней","is_correct":false}]',
 'По аналитике CRM за 2025 год, средний цикл проекта в Асгарде составляет 45 дней.'),
(lid, 6, 'truefalse', 'Акты скрытых работ можно оформить после завершения всех работ на объекте.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]',
 'Акты скрытых работ оформляются ДО того, как следующий слой закроет предыдущий. Откладывать их на потом недопустимо — заказчик не подпишет акт без возможности проверки.'),
(lid, 7, 'scenario', 'Мастер на объекте предлагает выполнить дополнительные работы для заказчика без оформления допсоглашения, «чтобы не терять время». Что должен сделать РП?',
 '[{"text":"Согласиться — клиент будет доволен и заплатит потом","is_correct":false},{"text":"Остановить и оформить допсоглашение до начала работ","is_correct":true},{"text":"Выполнить работы и оформить документы задним числом","is_correct":false},{"text":"Отказать заказчику в дополнительных работах","is_correct":false}]',
 'Правильно — остановиться и оформить дополнительное соглашение ПЕРЕД началом работ. В 2023 году компания потеряла 4,2 млн рублей из-за работ без договора.'),
(lid, 8, 'choice', 'Сколько убыточных проектов было у Асгарда в 2025 году и какова их общая причина?',
 '[{"text":"1 проект — ошибка в смете","is_correct":false},{"text":"3 проекта — отсутствие допсоглашений","is_correct":true},{"text":"5 проектов — задержки поставок","is_correct":false},{"text":"0 — все проекты были прибыльными","is_correct":false}]',
 'Три проекта были убыточными, и во всех трёх случаях причиной стало отсутствие допсоглашений на дополнительные объёмы работ.'),
(lid, 9, 'choice', 'За сколько дней до выезда нужно заказать оборудование и материалы через отдел закупок?',
 '[{"text":"За 2 дня","is_correct":false},{"text":"За 3 дня","is_correct":false},{"text":"За 5 дней","is_correct":true},{"text":"За 10 дней","is_correct":false}]',
 'Оборудование и материалы заказываются через отдел закупок минимум за 5 дней до выезда бригады на объект.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОК 2: Планирование работ
-- ═══════════════════════════════════════════════════════════════
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons
  (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (3, 'pm', 'Планирование работ — WBS, графики и критический путь', 'Искусство руководства', '📋', '#1e3040',
$blocks$[
  {"type":"cover","icon":"📋","title":"Планирование работ","subtitle":"WBS, диаграммы Ганта и метод критического пути"},
  {"type":"intro","text":"Планирование — это 80% успеха проекта. Без чёткого плана даже опытная бригада теряет время, деньги и нервы. В этом свитке разберём три главных инструмента планирования: декомпозицию работ (WBS), диаграмму Ганта и метод критического пути. Каждый из них РП Асгарда обязан уметь применять на практике — от простого проекта промывки до комплексного ремонта установки."},
  {"type":"text_block","title":"WBS — иерархическая структура работ","text":"WBS (Work Breakdown Structure) — это декомпозиция проекта на управляемые пакеты работ. Принцип простой: большую задачу разбиваем на части, каждую часть — ещё на подзадачи, пока не дойдём до элементарных операций, которые можно оценить по времени и стоимости. Для проекта химической промывки WBS выглядит так: уровень 1 — весь проект, уровень 2 — мобилизация, подготовка, промывка, контроль качества, демобилизация. Уровень 3 детализирует каждый этап: например, «промывка» разбивается на заполнение системы раствором, циркуляцию, дренаж, промывку водой, нейтрализацию. Каждый элемент WBS должен иметь ответственного, срок и стоимость. Правило: если задача занимает больше 5 дней — её нужно декомпозировать дальше."},
  {"type":"icon_grid","title":"Уровни WBS для проекта промывки","items":[{"icon":"🏗️","label":"Мобилизация","desc":"Доставка бригады, оборудования, заезд на объект, инструктажи"},{"icon":"🔧","label":"Подготовка","desc":"Монтаж обвязки, подключение насосов, заполнение системы"},{"icon":"🧪","label":"Промывка","desc":"Циркуляция раствора, контроль параметров, дренаж"},{"icon":"🔍","label":"Контроль","desc":"Визуальный осмотр, замеры толщин, протоколы"},{"icon":"📝","label":"Документация","desc":"Акты, протоколы, фотоотчёты, КС-2"},{"icon":"🚛","label":"Демобилизация","desc":"Разборка обвязки, утилизация отходов, вывоз оборудования"}]},
  {"type":"text_block","title":"Диаграмма Ганта — визуальный график","text":"Диаграмма Ганта — горизонтальный график, где каждая задача показана полоской от начала до окончания. Главное преимущество — наглядность: вы сразу видите, какие задачи идут параллельно, а какие последовательно. В Асгарде график Ганта строится в CRM для каждого проекта. Типичная ошибка начинающих РП — ставить все задачи последовательно, хотя многие можно выполнять параллельно. Например, пока бригада монтирует обвязку на первом теплообменнике, вторая бригада может готовить раствор. Параллельное выполнение сокращает общий срок проекта на 20-35%. Ганта не заменяет детального плана, но отлично подходит для коммуникации с заказчиком — показать прогресс и обосновать сроки."},
  {"type":"warning","level":"warning","text":"При планировании всегда закладывайте буфер 15-20% на непредвиденные обстоятельства. На промышленных объектах задержки случаются постоянно: заказчик не вовремя выводит оборудование из работы, поставщик задерживает реагенты, погода не позволяет работать на высоте. Проект без буфера — это проект, который гарантированно опоздает."},
  {"type":"text_block","title":"Метод критического пути (CPM)","text":"Критический путь — это самая длинная последовательность зависимых задач в проекте. Именно она определяет минимальный срок завершения проекта. Задержка любой задачи на критическом пути автоматически сдвигает весь проект. Задачи вне критического пути имеют «резерв времени» — их можно задержать без влияния на общий срок. Для РП важно знать свой критический путь наизусть. Пример: в проекте промывки 6 теплообменников критический путь обычно проходит через самый сложный аппарат — тот, который требует максимального времени циркуляции раствора. Все ресурсы в первую очередь направляются на задачи критического пути."},
  {"type":"steps","title":"Как построить план проекта за 1 час","items":["Составить WBS: разбить проект на 3-4 уровня вложенности до элементарных операций","Оценить длительность каждой операции (оптимистичная, реалистичная, пессимистичная)","Определить зависимости: какие задачи не могут начаться без завершения предыдущих","Найти критический путь — самую длинную цепочку зависимых задач","Оптимизировать: выделить задачи, которые можно выполнять параллельно","Добавить буфер 15-20% к общему сроку на непредвиденные обстоятельства","Согласовать график с мастером бригады и отделом закупок","Загрузить план в CRM Асгарда и отправить заказчику"]},
  {"type":"scenario","title":"Заказчик требует сократить сроки","text":"Вы спланировали проект промывки 8 теплообменников на 28 рабочих дней. Заказчик говорит: «У нас плановый останов всего 18 дней, либо укладываетесь, либо мы берём другого подрядчика». Бригада стандартная — 6 человек.","resolution":"Правильный подход: 1) Проанализировать критический путь и найти задачи для параллельного выполнения. 2) Рассчитать стоимость второй бригады — если 12 человек могут работать на 2-3 аппаратах одновременно, срок сокращается до 16-18 дней. 3) Пересчитать смету с учётом дополнительных расходов на вторую бригаду. 4) Предложить заказчику вариант с доплатой за ускорение. Никогда не соглашайтесь на сокращение сроков без пересчёта ресурсов."},
  {"type":"stat","value":"20-35%","label":"экономия времени при параллельном выполнении задач вместо последовательного","source":"Практика проектов Асгарда"},
  {"type":"fact_card","icon":"⏱️","text":"Исследование PMI (Project Management Institute) показало, что проекты с детальным планированием завершаются в срок в 73% случаев, а без плана — только в 31%. В Асгарде за 2025 год 89% проектов с полным планом в CRM завершились в срок, тогда как из проектов без плана — только 52%."},
  {"type":"highlight","text":"Правило «5 дней»: если задача в WBS длится больше 5 рабочих дней — декомпозируй её дальше. Задачи больше 5 дней невозможно точно контролировать."},
  {"type":"quote","text":"Планы бесполезны, но планирование бесценно","author":"Дуайт Эйзенхауэр"},
  {"type":"checklist","title":"Чек-лист качественного плана","items":["WBS декомпозирован до уровня задач ≤5 дней","Каждая задача имеет ответственного и срок","Определены зависимости между задачами","Критический путь найден и выделен","Буфер 15-20% заложен в общий срок","План согласован с мастером и закупками","График загружен в CRM"]},
  {"type":"divider"}
]$blocks$::jsonb,
10, ARRAY['планирование','WBS','Гант','критический путь','график'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'Какой максимальный срок задачи в WBS по правилу Асгарда?',
 '[{"text":"3 дня","is_correct":false},{"text":"5 дней","is_correct":true},{"text":"7 дней","is_correct":false},{"text":"10 дней","is_correct":false}]',
 'Правило «5 дней»: если задача длится больше 5 рабочих дней — её нужно декомпозировать дальше.'),
(lid, 2, 'choice', 'Какой процент буфера нужно закладывать при планировании?',
 '[{"text":"5-10%","is_correct":false},{"text":"15-20%","is_correct":true},{"text":"25-30%","is_correct":false},{"text":"40-50%","is_correct":false}]',
 'При планировании всегда закладывается буфер 15-20% на непредвиденные обстоятельства.'),
(lid, 3, 'choice', 'На сколько процентов параллельное выполнение задач сокращает общий срок проекта?',
 '[{"text":"10-15%","is_correct":false},{"text":"20-35%","is_correct":true},{"text":"40-50%","is_correct":false},{"text":"50-60%","is_correct":false}]',
 'Параллельное выполнение задач сокращает общий срок проекта на 20-35% по практике Асгарда.'),
(lid, 4, 'choice', 'Какой процент проектов с детальным планом в CRM завершился в срок в Асгарде за 2025 год?',
 '[{"text":"73%","is_correct":false},{"text":"82%","is_correct":false},{"text":"89%","is_correct":true},{"text":"95%","is_correct":false}]',
 'За 2025 год 89% проектов с полным планом в CRM завершились в срок, против 52% без плана.'),
(lid, 5, 'truefalse', 'Критический путь — это самая короткая последовательность задач в проекте.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]',
 'Критический путь — это САМАЯ ДЛИННАЯ последовательность зависимых задач. Именно она определяет минимальный срок завершения проекта.'),
(lid, 6, 'choice', 'Что такое WBS?',
 '[{"text":"Система управления рисками","is_correct":false},{"text":"Иерархическая структура работ","is_correct":true},{"text":"График загрузки ресурсов","is_correct":false},{"text":"Финансовый план проекта","is_correct":false}]',
 'WBS (Work Breakdown Structure) — это иерархическая структура работ, декомпозиция проекта на управляемые пакеты работ.'),
(lid, 7, 'scenario', 'Заказчик требует сократить 28-дневный проект до 18 дней. Какой правильный подход?',
 '[{"text":"Согласиться и работать быстрее","is_correct":false},{"text":"Отказаться — сроки невозможно сократить","is_correct":false},{"text":"Пересчитать с доп. бригадой и предложить вариант с доплатой","is_correct":true},{"text":"Убрать буфер из плана и уложиться в 18 дней","is_correct":false}]',
 'Правильно: проанализировать критический путь, рассчитать стоимость второй бригады для параллельной работы, предложить заказчику вариант с доплатой за ускорение.'),
(lid, 8, 'choice', 'Какой процент проектов без плана завершается в срок по данным PMI?',
 '[{"text":"31%","is_correct":true},{"text":"45%","is_correct":false},{"text":"55%","is_correct":false},{"text":"65%","is_correct":false}]',
 'По данным PMI, проекты без детального планирования завершаются в срок только в 31% случаев.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОК 3: Управление бригадами
-- ═══════════════════════════════════════════════════════════════
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons
  (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (4, 'pm', 'Управление бригадами — мотивация, конфликты, ротация', 'Искусство руководства', '👥', '#1e2838',
$blocks$[
  {"type":"cover","icon":"👥","title":"Управление бригадами","subtitle":"Как собрать, мотивировать и удержать сильную команду"},
  {"type":"intro","text":"Бригада — это главный актив проекта. Самый идеальный план и самое дорогое оборудование бесполезны, если бригада не работает слаженно. РП Асгарда управляет людьми в экстремальных условиях: вахта, удалённость, опасные вещества, жёсткие сроки. В этом свитке — практические техники управления бригадами, проверенные на десятках проектов."},
  {"type":"text_block","title":"Формирование бригады: кого и сколько","text":"Стандартная бригада Асгарда для проекта химической промывки — 6-8 человек: мастер (старший), 2 аппаратчика, 2 монтажника, слесарь-трубопроводчик, стропальщик. Для проектов теплоизоляции состав другой: мастер, 4-6 изолировщиков, жестянщик, подсобный рабочий. Ключевое правило — в каждой бригаде минимум 2 человека с опытом работы на данном типе оборудования. Нельзя отправлять полностью «зелёную» бригаду. Мастер подбирается из тех, кто уже работал на объектах этого заказчика — знание правил и людей заказчика экономит 2-3 дня адаптации. В CRM Асгарда есть рейтинг каждого рабочего по навыкам, объектам и отзывам мастеров."},
  {"type":"icon_grid","title":"Роли в бригаде","items":[{"icon":"👷","label":"Мастер","desc":"Старший бригады. Отвечает за ТБ, качество, ежедневные отчёты РП"},{"icon":"🧪","label":"Аппаратчик","desc":"Работа с химическими растворами, контроль параметров промывки"},{"icon":"🔧","label":"Монтажник","desc":"Монтаж/демонтаж обвязки, подключение насосов, трубопроводов"},{"icon":"⚡","label":"Сварщик НАКС","desc":"Сварочные работы — только с аттестацией НАКС по нужному способу"},{"icon":"🏗️","label":"Стропальщик","desc":"Работы с грузоподъёмными механизмами, такелаж"},{"icon":"📋","label":"Подсобный","desc":"Вспомогательные работы, уборка, подготовка площадки"}]},
  {"type":"text_block","title":"Мотивация на вахте: что реально работает","text":"Забудьте про корпоративные тренинги и тимбилдинги — на вахте работают другие инструменты мотивации. Первое и главное — справедливая оплата без задержек. Суточные должны приходить вовремя, зарплата — в обещанный день. Второе — условия проживания: тёплое жильё, нормальная еда, горячая вода. РП, который выбил для бригады гостиницу вместо вагончика, получает лояльность на весь проект. Третье — уважение и обратная связь. Ежедневная планёрка на 10-15 минут, где мастер и РП обсуждают план дня, проблемы и достижения. Четвёртое — бонус за досрочное завершение: если бригада закончила на 3+ дня раньше — премия каждому. Это работает безотказно."},
  {"type":"warning","level":"danger","text":"Никогда не задерживайте выплату суточных и зарплаты бригаде. Задержка даже на 2-3 дня разрушает доверие и мотивацию. В практике Асгарда были случаи, когда бригада отказывалась выходить на смену из-за задержки суточных — простой на НПЗ стоит 200-500 тысяч рублей в день. Если видите проблему с финансированием — эскалируйте немедленно."},
  {"type":"text_block","title":"Конфликты: предотвращение и решение","text":"Конфликты на вахте неизбежны: люди живут и работают вместе 24/7 в стрессовых условиях. Задача РП — не допустить эскалации. Три главных типа конфликтов: 1) Рабочие vs рабочие — обычно из-за распределения задач или бытовых мелочей. Решение — чёткое распределение обязанностей и жёсткий порядок в бытовке. 2) Бригада vs заказчик — из-за требований ТБ, пропускного режима, условий работы. Решение — РП берёт коммуникацию на себя, не допуская прямых конфликтов. 3) Мастер vs рабочие — из-за стиля управления. Решение — регулярные беседы с мастером, обратная связь от бригады через анонимный опрос в CRM."},
  {"type":"steps","title":"Алгоритм решения конфликта в бригаде","items":["Выслушать обе стороны отдельно, не при свидетелях","Зафиксировать факты: что произошло, когда, при каких обстоятельствах","Определить корневую причину: несправедливость, усталость, личная неприязнь, условия","Предложить решение: перераспределить задачи, развести по сменам, заменить","Получить согласие обеих сторон на решение","Проконтролировать исполнение через 2-3 дня","Если конфликт повторяется — заменить одного из участников на следующей вахте"]},
  {"type":"scenario","title":"Два рабочих не ладят на вахте","text":"Два опытных аппаратчика — Сергей и Дмитрий — конфликтуют третий день подряд. Сергей считает, что Дмитрий плохо промывает систему, Дмитрий — что Сергей командует, хотя не является мастером. Мастер пожимает плечами: «Пусть сами разбираются». Бригада разделилась на два лагеря. Качество работ падает.","resolution":"РП должен: 1) Поговорить с каждым отдельно — выяснить реальную причину. 2) Проверить претензии Сергея к качеству — если обоснованы, это рабочий вопрос, а не личный. 3) Разделить их по разным аппаратам/сменам на оставшийся период. 4) Провести разговор с мастером — его обязанность решать такие ситуации, а не «пожимать плечами». 5) Зафиксировать инцидент в CRM для учёта при формировании будущих бригад — не ставить этих двоих вместе."},
  {"type":"text_block","title":"Ротация: когда и как менять состав","text":"Оптимальный срок вахты в Асгарде — 28 дней (4 недели). При более длительных проектах обязательна ротация — замена части бригады каждые 28-30 дней. При ротации критически важно обеспечить перехлёст: новая смена приезжает за 1-2 дня до отъезда старой, чтобы передать дела на месте. Мастер готовит акт передачи: что сделано, что осталось, где проблемные места, какие договорённости с заказчиком. Без перехлёста неизбежны потери 3-5 дней на вхождение новой смены в курс дела."},
  {"type":"stat","value":"28 дней","label":"оптимальный срок вахты — после этого эффективность падает на 15-20%","source":"HR-аналитика Асгарда"},
  {"type":"fact_card","icon":"💡","text":"Исследования показывают, что производительность на вахте начинает падать после 21-го дня: усталость, однообразие, тоска по дому. К 28-му дню падение составляет 15-20%. После 35 дней резко растёт травматизм. Поэтому оптимальный цикл — 28/28 (28 дней работы, 28 дней отдыха)."},
  {"type":"highlight","text":"Золотое правило мотивации на вахте: справедливая оплата вовремя + нормальные бытовые условия + уважение и обратная связь + бонус за результат. Всё остальное — вторично."},
  {"type":"quote","text":"Люди уходят не из компании — они уходят от руководителей","author":"Маркус Бакингем"},
  {"type":"checklist","title":"Чек-лист формирования бригады","items":["Минимум 2 человека с опытом на данном типе оборудования","Мастер с опытом на объектах этого заказчика","Все допуски и медосмотры актуальны","Проверен рейтинг и отзывы в CRM","Конфликтные пары разведены по разным бригадам","Суточные и зарплата утверждены и профинансированы","Перехлёст при ротации запланирован (1-2 дня)"]},
  {"type":"divider"}
]$blocks$::jsonb,
11, ARRAY['бригада','мотивация','конфликты','вахта','ротация'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'Каков оптимальный срок вахты в Асгарде?',
 '[{"text":"14 дней","is_correct":false},{"text":"21 день","is_correct":false},{"text":"28 дней","is_correct":true},{"text":"45 дней","is_correct":false}]',
 'Оптимальный срок вахты — 28 дней. После этого эффективность падает на 15-20%.'),
(lid, 2, 'choice', 'Сколько дней перехлёста нужно при ротации бригады?',
 '[{"text":"Перехлёст не нужен","is_correct":false},{"text":"1-2 дня","is_correct":true},{"text":"3-5 дней","is_correct":false},{"text":"7 дней","is_correct":false}]',
 'При ротации новая смена приезжает за 1-2 дня до отъезда старой для передачи дел на месте.'),
(lid, 3, 'choice', 'Какой стандартный состав бригады для проекта химической промывки?',
 '[{"text":"3-4 человека","is_correct":false},{"text":"6-8 человек","is_correct":true},{"text":"10-12 человек","is_correct":false},{"text":"15-20 человек","is_correct":false}]',
 'Стандартная бригада для химической промывки — 6-8 человек: мастер, аппаратчики, монтажники, слесарь, стропальщик.'),
(lid, 4, 'truefalse', 'Можно отправить на объект бригаду, где ни один человек не работал на данном типе оборудования.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]',
 'В каждой бригаде должно быть минимум 2 человека с опытом работы на данном типе оборудования.'),
(lid, 5, 'choice', 'Сколько стоит простой бригады на НПЗ из-за задержки суточных?',
 '[{"text":"50-100 тыс руб/день","is_correct":false},{"text":"200-500 тыс руб/день","is_correct":true},{"text":"1-2 млн руб/день","is_correct":false},{"text":"Простоя не будет","is_correct":false}]',
 'Простой на НПЗ стоит 200-500 тысяч рублей в день. Задержка суточных даже на 2-3 дня может привести к отказу бригады выходить на смену.'),
(lid, 6, 'choice', 'На сколько процентов падает эффективность после 28 дней вахты?',
 '[{"text":"5-10%","is_correct":false},{"text":"15-20%","is_correct":true},{"text":"25-30%","is_correct":false},{"text":"40-50%","is_correct":false}]',
 'К 28-му дню падение производительности составляет 15-20%, а после 35 дней резко растёт травматизм.'),
(lid, 7, 'scenario', 'Два опытных рабочих конфликтуют, мастер не вмешивается. Что делать РП?',
 '[{"text":"Подождать — сами разберутся","is_correct":false},{"text":"Уволить обоих","is_correct":false},{"text":"Поговорить отдельно, разделить по сменам, провести работу с мастером","is_correct":true},{"text":"Собрать всю бригаду и устроить разбор при всех","is_correct":false}]',
 'Правильно: выслушать каждого отдельно, проверить претензии, разделить по аппаратам/сменам, провести разговор с мастером о его обязанностях, зафиксировать в CRM.'),
(lid, 8, 'choice', 'Сколько дней адаптации экономит мастер с опытом работы у данного заказчика?',
 '[{"text":"1 день","is_correct":false},{"text":"2-3 дня","is_correct":true},{"text":"5-7 дней","is_correct":false},{"text":"10 дней","is_correct":false}]',
 'Мастер, который уже работал на объектах этого заказчика, знает правила и людей — это экономит 2-3 дня адаптации.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОК 4: Бюджетирование проекта
-- ═══════════════════════════════════════════════════════════════
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons
  (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (5, 'pm', 'Бюджетирование проекта — сметы, контроль затрат, маржа', 'Искусство руководства', '💰', '#1e2e18',
$blocks$[
  {"type":"cover","icon":"💰","title":"Бюджетирование проекта","subtitle":"Как считать, контролировать и не терять деньги"},
  {"type":"intro","text":"Деньги — кровь проекта. РП, который не контролирует бюджет — не управляет проектом. В Асгарде каждый руководитель проекта несёт персональную ответственность за финансовый результат. Убыточный проект — это не просто потеря прибыли, это удар по компании и по репутации РП. В этом свитке — всё о бюджетировании: от составления сметы до финального финансового отчёта."},
  {"type":"text_block","title":"Структура себестоимости проекта","text":"Себестоимость проекта в Асгарде складывается из пяти основных статей. Первая — фонд оплаты труда (ФОТ): зарплата бригады, суточные, командировочные, налоги и взносы. ФОТ обычно составляет 35-45% себестоимости. Вторая — материалы и реагенты: химические составы для промывки, изоляционные материалы, расходники. Это 15-25%. Третья — логистика: доставка бригады и оборудования, проживание, питание — 10-15%. Четвёртая — аренда оборудования: насосы, компрессоры, подъёмные механизмы — 5-10%. Пятая — накладные расходы: офис, управление, страхование — 10-15%. Сумма этих статей — себестоимость. Разница между ценой для заказчика и себестоимостью — маржа."},
  {"type":"icon_grid","title":"Статьи себестоимости проекта","items":[{"icon":"👷","label":"ФОТ (35-45%)","desc":"Зарплата, суточные, командировочные, налоги и взносы"},{"icon":"🧪","label":"Материалы (15-25%)","desc":"Реагенты, изоляция, расходные материалы, крепёж"},{"icon":"🚛","label":"Логистика (10-15%)","desc":"Билеты, проживание, питание, доставка оборудования"},{"icon":"🔧","label":"Оборудование (5-10%)","desc":"Аренда насосов, компрессоров, спецтехники"},{"icon":"🏢","label":"Накладные (10-15%)","desc":"Офис, управление, страхование, связь"},{"icon":"📊","label":"Маржа (≥25%)","desc":"Минимальная прибыль — правило Асгарда"}]},
  {"type":"warning","level":"danger","text":"Три главных убийцы маржи: 1) Недооценка ФОТ — забыли учесть переработки, ночные смены, налоги 30,2%. 2) Дополнительные работы без допсоглашения — сделали «по-дружески», заказчик не заплатил. 3) Перерасход материалов — заказали впритык, на объекте обнаружили брак, пришлось докупать по двойной цене с экспресс-доставкой."},
  {"type":"text_block","title":"Мимир и автоматический просчёт","text":"В CRM Асгарда работает система Мимир — ИИ-помощник, который автоматически рассчитывает смету проекта на основе ТЗ. Мимир анализирует объёмы работ, подбирает нормативы расхода материалов, рассчитывает ФОТ с учётом разрядов рабочих и региональных коэффициентов. РП получает готовую смету за 10-15 минут вместо 2-3 часов ручного расчёта. Однако Мимир — помощник, а не замена РП. Всегда проверяйте расчёт: соответствуют ли нормативы реальному объекту, учтены ли особенности (высотные работы, ночные смены, сложный доступ). Маржа в расчёте Мимира должна быть не менее 25% — если ниже, система предупреждает РП."},
  {"type":"steps","title":"Алгоритм контроля бюджета на объекте","items":["Ежедневно фиксировать расход материалов в CRM — что использовано, сколько осталось","Еженедельно сверять факт ФОТ с планом — переработки, больничные, замены","Контролировать дополнительные расходы: непредвиденный ремонт, замена инструмента","При отклонении >10% от бюджета — немедленно эскалировать на коммерческого директора","Фиксировать все дополнительные работы — даже мелкие, для будущего допсоглашения","По завершении — составить финансовый отчёт: план vs факт по каждой статье"]},
  {"type":"scenario","title":"Бюджет трещит по швам","text":"Вы на середине проекта промывки 10 теплообменников на Омском НПЗ. При вскрытии обнаружилось, что 3 аппарата имеют сильные отложения, требующие двойной промывки. Расход реагентов увеличится на 40%, время — на 5 дней. Бюджет на материалы уже освоен на 60%, а работа выполнена на 50%.","resolution":"Правильно: 1) Немедленно составить акт обнаружения дополнительных отложений с фотофиксацией. 2) Пересчитать смету с учётом доп. объёмов. 3) Направить заказчику письмо с обоснованием и предложением допсоглашения. 4) Параллельно — заказать дополнительные реагенты, не дожидаясь ответа, чтобы не терять время. 5) Эскалировать на комдира для согласования допрасходов."},
  {"type":"stat","value":"25%","label":"минимальная маржинальность проекта — железное правило Асгарда","source":"Финансовая политика компании"},
  {"type":"text_block","title":"Финальный финансовый отчёт","text":"По завершении проекта РП обязан составить финансовый отчёт — сравнение плановых и фактических затрат по каждой статье. Отчёт формируется в CRM Асгарда автоматически на основе данных, введённых в процессе работы. Если фактическая маржа оказалась ниже плановой — РП должен написать пояснительную записку с указанием причин и предложениями по недопущению в будущем. Финансовый отчёт рассматривается на еженедельном совещании у коммерческого директора."},
  {"type":"fact_card","icon":"📉","text":"Анализ 200+ проектов Асгарда за 2024-2025 годы показал: главная причина снижения маржи — перерасход ФОТ из-за переработок (42% случаев). На втором месте — допработы без оплаты (28%). На третьем — перерасход материалов (18%). Только 12% отклонений вызваны объективными причинами."},
  {"type":"highlight","text":"Правило 10%: если фактические затраты отклоняются от бюджета более чем на 10% — это сигнал тревоги. РП обязан эскалировать ситуацию на коммерческого директора и составить план корректирующих действий."},
  {"type":"quote","text":"Не считать деньги — всё равно что управлять кораблём без компаса","author":"Питер Друкер"},
  {"type":"checklist","title":"Чек-лист бюджетного контроля","items":["Смета составлена и согласована до начала работ","Маржа ≥25% подтверждена","Ежедневный учёт расхода материалов в CRM","Еженедельная сверка ФОТ план/факт","Все допработы зафиксированы для допсоглашения","Отклонения >10% эскалированы немедленно","Финансовый отчёт составлен в течение 3 дней после завершения"]},
  {"type":"divider"}
]$blocks$::jsonb,
10, ARRAY['бюджет','смета','маржа','ФОТ','финансы','Мимир'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'Какую долю себестоимости обычно составляет ФОТ?',
 '[{"text":"15-25%","is_correct":false},{"text":"35-45%","is_correct":true},{"text":"50-60%","is_correct":false},{"text":"60-70%","is_correct":false}]',
 'Фонд оплаты труда (зарплата, суточные, командировочные, налоги) обычно составляет 35-45% себестоимости проекта.'),
(lid, 2, 'choice', 'Какова главная причина снижения маржи по анализу 200+ проектов Асгарда?',
 '[{"text":"Перерасход материалов","is_correct":false},{"text":"Перерасход ФОТ из-за переработок","is_correct":true},{"text":"Допработы без оплаты","is_correct":false},{"text":"Логистические задержки","is_correct":false}]',
 'Главная причина снижения маржи — перерасход ФОТ из-за переработок (42% случаев).'),
(lid, 3, 'choice', 'При каком отклонении от бюджета нужно эскалировать на коммерческого директора?',
 '[{"text":"Более 5%","is_correct":false},{"text":"Более 10%","is_correct":true},{"text":"Более 20%","is_correct":false},{"text":"Более 30%","is_correct":false}]',
 'Правило 10%: при отклонении фактических затрат от бюджета более чем на 10% — немедленная эскалация.'),
(lid, 4, 'choice', 'Сколько времени экономит Мимир при расчёте сметы?',
 '[{"text":"30 минут вместо 1 часа","is_correct":false},{"text":"10-15 минут вместо 2-3 часов","is_correct":true},{"text":"1 час вместо 1 дня","is_correct":false},{"text":"5 минут вместо 30 минут","is_correct":false}]',
 'Мимир рассчитывает смету за 10-15 минут вместо 2-3 часов ручного расчёта.'),
(lid, 5, 'truefalse', 'Расчёт Мимира можно использовать без проверки РП.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]',
 'Мимир — помощник, а не замена РП. Всегда нужно проверять: соответствуют ли нормативы реальному объекту, учтены ли особенности.'),
(lid, 6, 'choice', 'Какой процент отклонений маржи вызван объективными причинами?',
 '[{"text":"12%","is_correct":true},{"text":"28%","is_correct":false},{"text":"42%","is_correct":false},{"text":"55%","is_correct":false}]',
 'Только 12% отклонений вызваны объективными причинами. 42% — перерасход ФОТ, 28% — допработы без оплаты, 18% — перерасход материалов.'),
(lid, 7, 'scenario', 'На объекте обнаружились дополнительные отложения, расход реагентов вырастет на 40%. Что делать?',
 '[{"text":"Продолжать работу и разбираться с деньгами потом","is_correct":false},{"text":"Составить акт, пересчитать смету, направить допсоглашение заказчику","is_correct":true},{"text":"Прекратить работы до получения оплаты","is_correct":false},{"text":"Использовать более дешёвые реагенты","is_correct":false}]',
 'Правильно: акт обнаружения с фото → пересчёт сметы → письмо заказчику с допсоглашением → параллельно заказ реагентов → эскалация на комдира.'),
(lid, 8, 'choice', 'В какой срок после завершения проекта нужно составить финансовый отчёт?',
 '[{"text":"В тот же день","is_correct":false},{"text":"В течение 3 дней","is_correct":true},{"text":"В течение недели","is_correct":false},{"text":"В течение месяца","is_correct":false}]',
 'Финансовый отчёт (план vs факт по каждой статье) составляется в течение 3 дней после завершения проекта.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОКИ 5-8 (обязательные) — краткая версия для экономии места
-- Полный контент аналогичен урокам 1-4
-- ═══════════════════════════════════════════════════════════════

-- УРОК 5: Отчётность и KPI
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (6, 'pm', 'Отчётность и KPI руководителя проекта', 'Искусство руководства', '📊', '#182e40',
$blocks$[
  {"type":"cover","icon":"📊","title":"Отчётность и KPI","subtitle":"Метрики, дашборды и еженедельные отчёты"},
  {"type":"intro","text":"То, что не измеряется — не управляется. KPI руководителя проекта в Асгарде — это не абстрактные показатели из учебника, а конкретные цифры, которые еженедельно разбираются на совещании у директора. В этом свитке — все метрики, которые должен знать и контролировать каждый РП."},
  {"type":"text_block","title":"7 ключевых KPI руководителя проекта","text":"В Асгарде действует система из 7 основных KPI для РП. Первый — маржинальность проекта (план ≥25%, факт по итогу). Второй — выполнение сроков: отклонение от плана в днях. Третий — индекс качества: количество рекламаций и дефектов на проект. Четвёртый — утилизация бригады: процент рабочего времени, потраченного на продуктивную работу (норма ≥85%). Пятый — NPS заказчика: оценка удовлетворённости по 10-балльной шкале после каждого проекта (норма ≥8). Шестой — документооборот: срок закрытия КС-2/КС-3 после завершения работ (норма ≤5 рабочих дней). Седьмой — безопасность: количество инцидентов и нарушений ТБ на проекте (цель — ноль)."},
  {"type":"icon_grid","title":"Дашборд РП в CRM","items":[{"icon":"💰","label":"Маржа ≥25%","desc":"Плановая и фактическая маржинальность каждого проекта"},{"icon":"⏱️","label":"Сроки ±0 дней","desc":"Отклонение от графика — зелёный/жёлтый/красный"},{"icon":"⭐","label":"NPS ≥8","desc":"Оценка заказчика по 10-балльной шкале"},{"icon":"📝","label":"КС ≤5 дней","desc":"Срок закрытия документации после завершения"},{"icon":"👷","label":"Утилизация ≥85%","desc":"Процент продуктивного рабочего времени бригады"},{"icon":"🛡️","label":"ТБ = 0","desc":"Ноль инцидентов и нарушений техники безопасности"}]},
  {"type":"text_block","title":"Еженедельный отчёт: формат и содержание","text":"Каждый понедельник до 12:00 РП отправляет еженедельный отчёт по всем активным проектам. Формат стандартный: статус (зелёный/жёлтый/красный), прогресс в процентах, отклонения от плана, риски, потребности. Отчёт формируется в CRM автоматически — РП добавляет только комментарии и оценку рисков. На совещании у коммерческого директора разбираются проекты со статусом «жёлтый» и «красный». Зелёные — кратко, 30 секунд. Жёлтые — 2-3 минуты с планом корректировки. Красные — детальный разбор с участием всех заинтересованных."},
  {"type":"warning","level":"warning","text":"Никогда не красьте проект зелёным, если он жёлтый или красный. Оптимизм РП — главная причина того, что проблемы обнаруживаются слишком поздно. Лучше поднять тревогу раньше и получить помощь, чем скрывать проблему и получить убыточный проект."},
  {"type":"steps","title":"Как читать дашборд проекта в CRM","items":["Открыть раздел «Мои проекты» — список всех активных проектов","Проверить цвет статуса: 🟢 в плане, 🟡 риск отклонения, 🔴 критическое отклонение","Посмотреть график Ганта — какие задачи отстают от плана","Проверить бюджет: план vs факт по каждой статье расходов","Посмотреть фотоотчёты бригады — есть ли за последние 24 часа","Проверить дефектную ведомость — есть ли открытые замечания заказчика","Сформировать еженедельный отчёт и добавить комментарии"]},
  {"type":"stat","value":"85%","label":"норма утилизации бригады — процент продуктивного рабочего времени","source":"KPI Асгарда"},
  {"type":"fact_card","icon":"📈","text":"Анализ показал: РП, которые ведут дашборд в CRM ежедневно, завершают проекты с маржой в среднем на 4,7% выше, чем те, кто обновляет данные раз в неделю. Регулярный контроль позволяет ловить отклонения на ранней стадии."},
  {"type":"scenario","title":"Проект «зелёный», но маржа тает","text":"Ваш проект идёт по графику, заказчик доволен, бригада работает хорошо. Но при проверке бюджета вы обнаруживаете, что фактические расходы на ФОТ уже на 18% выше плана из-за переработок. Маржа упала с 28% до 19%. Формально проект «зелёный» — сроки соблюдаются.","resolution":"Статус проекта нужно сменить на «жёлтый». Маржа ниже 25% — это нарушение финансовой политики. РП должен: 1) Проанализировать причины переработок. 2) Оптимизировать график — возможно, лучше добавить человека, чем платить за переработки. 3) Доложить комдиру на еженедельном совещании. 4) Составить план возврата маржи к 25%."},
  {"type":"highlight","text":"Дедлайн еженедельного отчёта — понедельник 12:00. Опоздание без уважительной причины = жёлтый флаг для РП."},
  {"type":"quote","text":"Если вы не можете измерить это — вы не можете улучшить это","author":"Питер Друкер"},
  {"type":"checklist","title":"Чек-лист еженедельного отчёта","items":["Статус каждого проекта обновлён (🟢/🟡/🔴)","Прогресс в % актуален","Бюджет: план vs факт сверен","Риски описаны с оценкой влияния","Фотоотчёт бригады проверен","Комментарии добавлены","Отправлен до 12:00 понедельника"]},
  {"type":"divider"}
]$blocks$::jsonb,
9, ARRAY['KPI','отчётность','дашборд','метрики','NPS'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'Какой минимальный NPS заказчика является нормой в Асгарде?',
 '[{"text":"6","is_correct":false},{"text":"7","is_correct":false},{"text":"8","is_correct":true},{"text":"9","is_correct":false}]', 'Норма NPS заказчика — ≥8 из 10 баллов после каждого проекта.'),
(lid, 2, 'choice', 'В какой срок нужно закрыть КС-2/КС-3 после завершения работ?',
 '[{"text":"3 дня","is_correct":false},{"text":"5 дней","is_correct":true},{"text":"10 дней","is_correct":false},{"text":"14 дней","is_correct":false}]', 'Норма закрытия документации — ≤5 рабочих дней после завершения работ.'),
(lid, 3, 'choice', 'Сколько KPI действует для РП в Асгарде?',
 '[{"text":"5","is_correct":false},{"text":"7","is_correct":true},{"text":"10","is_correct":false},{"text":"12","is_correct":false}]', 'В Асгарде действует система из 7 основных KPI для руководителя проекта.'),
(lid, 4, 'choice', 'На сколько процентов выше маржа у РП, ведущих дашборд ежедневно?',
 '[{"text":"2,3%","is_correct":false},{"text":"4,7%","is_correct":true},{"text":"7,1%","is_correct":false},{"text":"10%","is_correct":false}]', 'РП с ежедневным ведением дашборда завершают проекты с маржой в среднем на 4,7% выше.'),
(lid, 5, 'truefalse', 'Если проект идёт по графику, но маржа упала ниже 25%, статус можно оставить зелёным.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]', 'Маржа ниже 25% — нарушение финансовой политики. Статус нужно сменить на жёлтый и эскалировать.'),
(lid, 6, 'choice', 'До какого времени в понедельник нужно отправить еженедельный отчёт?',
 '[{"text":"09:00","is_correct":false},{"text":"12:00","is_correct":true},{"text":"15:00","is_correct":false},{"text":"18:00","is_correct":false}]', 'Дедлайн еженедельного отчёта — понедельник 12:00.'),
(lid, 7, 'choice', 'Какова норма утилизации бригады?',
 '[{"text":"70%","is_correct":false},{"text":"75%","is_correct":false},{"text":"85%","is_correct":true},{"text":"95%","is_correct":false}]', 'Норма утилизации бригады — ≥85% продуктивного рабочего времени.'),
(lid, 8, 'scenario', 'Маржа проекта упала с 28% до 19% из-за переработок, но сроки соблюдаются. Какой статус поставить?',
 '[{"text":"Зелёный — сроки в порядке","is_correct":false},{"text":"Жёлтый — маржа ниже нормы","is_correct":true},{"text":"Красный — критическая ситуация","is_correct":false},{"text":"Оставить без статуса","is_correct":false}]', 'Маржа 19% < 25% нормы — статус жёлтый. Нужно проанализировать причины и составить план возврата маржи.');
END $$;

-- УРОК 6: Управление рисками
DO $$
DECLARE lid INT;
BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (7, 'pm', 'Управление рисками — матрица, митигация, эскалация', 'Искусство руководства', '⚠️', '#2e1e18',
$blocks$[
  {"type":"cover","icon":"⚠️","title":"Управление рисками","subtitle":"Как предвидеть проблемы и не тушить пожары"},
  {"type":"intro","text":"Риск — это не «если», а «когда». На промышленных объектах что-то всегда идёт не по плану: заказчик задерживает вывод оборудования, погода не позволяет работать, поставщик срывает сроки, рабочий заболевает. Задача РП — не избежать рисков (это невозможно), а управлять ими: предвидеть, оценить, подготовить план реагирования."},
  {"type":"text_block","title":"Матрица рисков: вероятность × влияние","text":"Матрица рисков — главный инструмент РП. Каждый риск оценивается по двум шкалам: вероятность наступления (низкая/средняя/высокая) и влияние на проект (незначительное/умеренное/критическое). Риски с высокой вероятностью И критическим влиянием — это «красная зона», требующая немедленного плана реагирования. Типичные красные риски для Асгарда: срыв поставки реагентов (вероятность средняя, влияние критическое — остановка работ), болезнь ключевого специалиста (вероятность средняя, влияние высокое), отказ оборудования заказчика (вероятность низкая, влияние критическое). Матрица составляется на этапе планирования и обновляется еженедельно."},
  {"type":"icon_grid","title":"Топ-6 рисков на проектах Асгарда","items":[{"icon":"🧪","label":"Срыв поставки","desc":"Реагенты или материалы не прибыли вовремя — простой бригады"},{"icon":"🤒","label":"Болезнь ключевого","desc":"Мастер или единственный сварщик НАКС выбыл — замена за 2-3 дня"},{"icon":"⛈️","label":"Погодные условия","desc":"Мороз <-25°C, ветер >15 м/с — запрет на высотные работы"},{"icon":"🔧","label":"Поломка оборудования","desc":"Отказ насоса или компрессора — ремонт или замена"},{"icon":"📋","label":"Изменение ТЗ","desc":"Заказчик меняет объём или технологию в процессе работ"},{"icon":"⚖️","label":"Претензия по качеству","desc":"Заказчик не принимает работы — доработка, повторная промывка"}]},
  {"type":"warning","level":"danger","text":"Самый опасный риск — тот, о котором РП не подумал. Проводите мозговой штурм рисков с мастером и опытными рабочими ПЕРЕД выездом на объект. Они знают реальность объекта лучше любого учебника. За 30 минут обсуждения можно выявить 80% потенциальных проблем."},
  {"type":"steps","title":"План реагирования на риск — шаблон","items":["Описать риск конкретно: что может произойти, при каких условиях","Оценить вероятность (1-5) и влияние (1-5), перемножить = приоритет","Определить триггер: по какому сигналу мы поймём, что риск наступает","Спланировать митигацию: что делаем ЗАРАНЕЕ, чтобы снизить вероятность","Спланировать реагирование: что делаем, ЕСЛИ риск наступил","Назначить ответственного за мониторинг этого риска","Определить порог эскалации: при каком уровне влияния подключаем руководство"]},
  {"type":"scenario","title":"Поставщик срывает сроки","text":"За 3 дня до выезда бригады поставщик реагентов сообщает, что партия задерживается на 7 дней из-за проблем на производстве. Без реагентов промывка невозможна. Заказчик уже вывел оборудование из работы и ждёт вашу бригаду.","resolution":"Если риск был в матрице (а он должен быть!): 1) Активировать запасного поставщика из списка — у Асгарда должно быть минимум 2 поставщика на каждый критичный материал. 2) Если запасной тоже не может — пересмотреть технологию: возможно, можно использовать альтернативный реагент. 3) Немедленно уведомить заказчика о возможной задержке — лучше предупредить, чем поставить перед фактом. 4) Параллельно — рассмотреть частичный заезд: бригада приезжает и выполняет подготовительные работы, пока реагенты в пути."},
  {"type":"text_block","title":"Эскалация: когда и кому","text":"Эскалация — это не признак слабости РП, а признак зрелости. Правило Асгарда: если риск угрожает срокам на 3+ дня, бюджету на 10%+ или качеству работ — эскалируй немедленно. Порядок эскалации: 1) коммерческий директор — финансовые и договорные вопросы, 2) технический директор — технологические проблемы и качество, 3) генеральный директор — вопросы репутации и стратегических заказчиков. Эскалация всегда в письменной форме через CRM с указанием: что произошло, какое влияние, что уже сделано, какая помощь нужна."},
  {"type":"stat","value":"80%","label":"рисков можно выявить за 30 минут мозгового штурма перед проектом","source":"Практика управления рисками Асгарда"},
  {"type":"fact_card","icon":"🔥","text":"В 2024 году на проекте в Тобольске бригада Асгарда обнаружила утечку кислоты из трубопровода заказчика во время промывки. Благодаря тому, что этот риск был в матрице и бригада знала план реагирования, утечка была локализована за 12 минут без пострадавших. Без подготовки последствия могли быть катастрофическими."},
  {"type":"highlight","text":"Минимум 2 поставщика на каждый критичный материал — правило Асгарда. Зависимость от одного поставщика = гарантированный риск простоя."},
  {"type":"quote","text":"Удача — это когда подготовка встречается с возможностью","author":"Сенека"},
  {"type":"divider"}
]$blocks$::jsonb,
10, ARRAY['риски','матрица','эскалация','митигация','план'], true, 'published', 'manual', NOW(), CURRENT_DATE)
RETURNING id INTO lid;

INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid, 1, 'choice', 'При каком отклонении от бюджета необходима эскалация?',
 '[{"text":"5%","is_correct":false},{"text":"10%","is_correct":true},{"text":"15%","is_correct":false},{"text":"20%","is_correct":false}]', 'Если риск угрожает бюджету на 10%+ — эскалируй немедленно.'),
(lid, 2, 'choice', 'Сколько процентов рисков можно выявить за 30 минут мозгового штурма?',
 '[{"text":"50%","is_correct":false},{"text":"65%","is_correct":false},{"text":"80%","is_correct":true},{"text":"95%","is_correct":false}]', 'За 30 минут обсуждения с мастером и опытными рабочими можно выявить 80% потенциальных проблем.'),
(lid, 3, 'choice', 'Сколько минимум поставщиков должно быть на каждый критичный материал?',
 '[{"text":"1","is_correct":false},{"text":"2","is_correct":true},{"text":"3","is_correct":false},{"text":"5","is_correct":false}]', 'Правило Асгарда: минимум 2 поставщика на каждый критичный материал.'),
(lid, 4, 'truefalse', 'Эскалация — это признак слабости руководителя проекта.',
 '[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]', 'Эскалация — это признак зрелости РП. Скрывать проблемы гораздо опаснее.'),
(lid, 5, 'choice', 'Кому эскалировать финансовые и договорные вопросы?',
 '[{"text":"Техническому директору","is_correct":false},{"text":"Коммерческому директору","is_correct":true},{"text":"Генеральному директору","is_correct":false},{"text":"HR-директору","is_correct":false}]', 'Порядок: коммерческий директор — финансовые и договорные, технический — технология и качество, генеральный — репутация и стратегия.'),
(lid, 6, 'choice', 'При угрозе срокам на сколько дней нужна эскалация?',
 '[{"text":"1+ день","is_correct":false},{"text":"3+ дня","is_correct":true},{"text":"5+ дней","is_correct":false},{"text":"7+ дней","is_correct":false}]', 'Если риск угрожает срокам на 3+ дня — немедленная эскалация.'),
(lid, 7, 'scenario', 'Поставщик реагентов срывает сроки на 7 дней. Какой первый шаг?',
 '[{"text":"Ждать поставку","is_correct":false},{"text":"Активировать запасного поставщика","is_correct":true},{"text":"Отменить проект","is_correct":false},{"text":"Отправить бригаду без реагентов","is_correct":false}]', 'Первый шаг — активировать запасного поставщика из списка. У Асгарда должно быть минимум 2 поставщика.'),
(lid, 8, 'choice', 'За сколько минут была локализована утечка кислоты на проекте в Тобольске?',
 '[{"text":"5 минут","is_correct":false},{"text":"12 минут","is_correct":true},{"text":"30 минут","is_correct":false},{"text":"1 час","is_correct":false}]', 'Утечка была локализована за 12 минут благодаря тому, что риск был в матрице и бригада знала план реагирования.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОКИ 7-12 — аналогичная структура
-- ═══════════════════════════════════════════════════════════════

-- УРОК 7: Работа с заказчиком
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (8, 'pm', 'Работа с заказчиком — коммуникация, ожидания, претензии', 'Искусство руководства', '🤝', '#1e2830', $blocks$[
  {"type":"cover","icon":"🤝","title":"Работа с заказчиком","subtitle":"Как строить доверие и решать спорные ситуации"},
  {"type":"intro","text":"Заказчик — это не враг и не друг. Это партнёр, с которым вы строите долгосрочные отношения. 70% повторных контрактов Асгарда приходят от заказчиков, довольных предыдущими проектами. Один неудачный проект может закрыть компанию для заказчика на годы. В этом свитке — техники профессиональной коммуникации с заказчиками промышленных объектов."},
  {"type":"text_block","title":"Правила коммуникации с представителем заказчика","text":"На каждом объекте у заказчика есть куратор проекта — обычно главный инженер или начальник цеха. Первая встреча — самая важная: представьтесь, покажите лицензии и допуски, обсудите план работ и правила взаимодействия. Установите регулярные точки контакта: ежедневная 10-минутная планёрка утром и краткий отчёт вечером. Все договорённости — письменно: email или запись в журнале. Устные обещания забываются и интерпретируются по-разному. Если возникает спорная ситуация — не спорьте на месте, возьмите паузу: «Давайте я проверю и вернусь с ответом через 2 часа». Эмоции — главный враг переговоров."},
  {"type":"warning","level":"warning","text":"Никогда не обещайте заказчику того, в чём не уверены. «Да, конечно сделаем» без проверки = будущая проблема. Лучше сказать: «Мне нужно 2 часа, чтобы проверить возможность и сроки» — это профессионально."},
  {"type":"steps","title":"Алгоритм работы с претензией заказчика","items":["Выслушать полностью, не перебивая. Записать все пункты претензии","Подтвердить, что вы поняли: «Правильно ли я понимаю, что...»","Не оправдываться и не обвинять — только факты","Взять паузу для анализа: «Мне нужно 4 часа / до завтра для проверки»","Провести внутреннее расследование: что произошло, кто ответственный","Подготовить ответ с планом корректирующих действий и сроками","Согласовать план с заказчиком и проконтролировать исполнение"]},
  {"type":"stat","value":"70%","label":"повторных контрактов — от довольных заказчиков","source":"Коммерческий отдел Асгарда"},
  {"type":"scenario","title":"Заказчик недоволен качеством промывки","text":"Главный инженер заказчика заявляет, что после промывки теплообменника остались отложения на 15% поверхности. Он требует повторную промывку за ваш счёт. Мастер говорит, что промывка выполнена по технологии и 85% — отличный результат.","resolution":"1) Не спорить на месте. 2) Проверить ТЗ — какой уровень очистки указан в договоре (обычно ≥90%). 3) Если 85% < договорного — признать замечание и выполнить доработку за свой счёт. 4) Если в ТЗ нет чёткого критерия — предложить совместный осмотр и согласование критерия. 5) Зафиксировать урок: в будущих договорах всегда прописывать критерий приёмки в цифрах."},
  {"type":"fact_card","icon":"🤝","text":"Компания Exxon Mobil ежегодно оценивает подрядчиков по 12 критериям. Подрядчики с рейтингом A получают приоритет на следующий год. Асгард входит в топ-3 подрядчиков на 4 заводах благодаря системной работе с обратной связью заказчиков."},
  {"type":"highlight","text":"Правило «2 часа»: при любом спорном вопросе от заказчика — не отвечайте сразу. Возьмите 2 часа на проверку фактов и подготовку ответа. Импульсивный ответ = 80% ошибок."},
  {"type":"quote","text":"Самый довольный клиент — тот, чья проблема была решена быстро и профессионально","author":"Джефф Безос"},
  {"type":"divider"}
]$blocks$::jsonb, 9, ARRAY['заказчик','коммуникация','претензии','NPS'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какой процент повторных контрактов приходит от довольных заказчиков?','[{"text":"40%","is_correct":false},{"text":"55%","is_correct":false},{"text":"70%","is_correct":true},{"text":"85%","is_correct":false}]','70% повторных контрактов Асгарда приходят от довольных заказчиков.'),
(lid,2,'choice','Сколько времени нужно взять на проверку при спорном вопросе?','[{"text":"30 минут","is_correct":false},{"text":"2 часа","is_correct":true},{"text":"1 день","is_correct":false},{"text":"1 неделю","is_correct":false}]','Правило «2 часа»: при спорном вопросе возьмите 2 часа на проверку фактов.'),
(lid,3,'truefalse','При претензии заказчика нужно сразу объяснить, почему он неправ.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Не оправдываться и не обвинять. Выслушать, записать, взять паузу для анализа.'),
(lid,4,'choice','Какой формат ежедневного контакта с куратором заказчика?','[{"text":"Только email раз в неделю","is_correct":false},{"text":"Планёрка утром + отчёт вечером","is_correct":true},{"text":"Звонок раз в 3 дня","is_correct":false},{"text":"Только при проблемах","is_correct":false}]','Установите ежедневную 10-минутную планёрку утром и краткий отчёт вечером.'),
(lid,5,'scenario','Заказчик говорит, что 85% очистки недостаточно. В ТЗ нет числового критерия. Что делать?','[{"text":"Настаивать, что 85% — отличный результат","is_correct":false},{"text":"Предложить совместный осмотр и согласование критерия","is_correct":true},{"text":"Промыть заново бесплатно","is_correct":false},{"text":"Отказаться от дальнейшей работы","is_correct":false}]','Если в ТЗ нет чёткого критерия — предложить совместный осмотр и согласование. В будущем прописывать критерий в цифрах.'),
(lid,6,'choice','Во сколько заводов Асгард входит в топ-3 подрядчиков?','[{"text":"2","is_correct":false},{"text":"4","is_correct":true},{"text":"6","is_correct":false},{"text":"10","is_correct":false}]','Асгард входит в топ-3 подрядчиков на 4 заводах.');
END $$;

-- УРОК 8: Документооборот проекта
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (9, 'pm', 'Документооборот проекта — КС-2, КС-3, исполнительная', 'Искусство руководства', '📝', '#182838', $blocks$[
  {"type":"cover","icon":"📝","title":"Документооборот проекта","subtitle":"КС-2, КС-3, акты скрытых работ и исполнительная документация"},
  {"type":"intro","text":"Документы — это деньги. Без правильно оформленных КС-2 и КС-3 заказчик не заплатит ни рубля. Без актов скрытых работ повторная экспертиза обойдётся в миллионы. В Асгарде документооборот — не бюрократия, а страховка от финансовых потерь и судебных споров."},
  {"type":"text_block","title":"КС-2 и КС-3: что это и зачем","text":"КС-2 — акт о приёмке выполненных работ. Это детальный документ, в котором перечислены все виды выполненных работ с указанием объёмов, единиц измерения, расценок и итоговой стоимости. КС-3 — справка о стоимости выполненных работ и затрат. Это сводный документ, который суммирует все КС-2 за период. Именно на основании КС-3 бухгалтерия заказчика производит оплату. Без подписанной КС-3 — нет оплаты. Типичная ошибка: РП отправляет КС-2 с ошибками в объёмах или расценках, заказчик возвращает на доработку, теряются 2-3 недели и деньги «зависают». Проверяйте каждую строку перед отправкой."},
  {"type":"icon_grid","title":"Комплект исполнительной документации","items":[{"icon":"📋","label":"КС-2","desc":"Акт приёмки — все работы с объёмами и расценками"},{"icon":"💰","label":"КС-3","desc":"Справка о стоимости — основание для оплаты"},{"icon":"🔍","label":"Акты скрытых работ","desc":"Фиксация работ, которые будут закрыты следующим слоем"},{"icon":"🧪","label":"Протоколы испытаний","desc":"Результаты контроля качества: толщины, чистота, давление"},{"icon":"📸","label":"Фотоотчёт","desc":"Фото до/после каждого этапа с привязкой к дате"},{"icon":"📄","label":"Сертификаты","desc":"Сертификаты на все использованные материалы и реагенты"}]},
  {"type":"warning","level":"danger","text":"Акты скрытых работ НЕЛЬЗЯ оформлять задним числом. Если заказчик обнаружит, что акт подписан после закрытия доступа к конструкции — это основание для отказа от приёмки всего объёма работ. Фиксируйте скрытые работы в день их выполнения."},
  {"type":"steps","title":"Алгоритм закрытия документации","items":["В процессе работ: ежедневно фиксировать объёмы в журнале и CRM","При скрытых работах: акт в тот же день, подпись представителя заказчика","По завершении: составить КС-2 по каждому виду работ (в течение 2 дней)","Проверить все расценки, объёмы, итоговые суммы — ошибки = задержка оплаты","Составить КС-3 на основании КС-2","Собрать полный комплект: КС-2, КС-3, акты, протоколы, фото, сертификаты","Отправить заказчику с сопроводительным письмом, зафиксировать в CRM"]},
  {"type":"stat","value":"5 дней","label":"максимальный срок закрытия КС-2/КС-3 после завершения работ — KPI Асгарда","source":"Финансовая политика"},
  {"type":"fact_card","icon":"💸","text":"В 2024 году средняя задержка оплаты по проектам с ошибками в КС-2 составила 23 дня, а по проектам с правильной документацией — только 7 дней. Разница в 16 дней на проекте стоимостью 20 млн рублей = 200+ тысяч рублей упущенной выгоды из-за замороженных средств."},
  {"type":"highlight","text":"Проверяй КС-2 трижды: сам, потом бухгалтер, потом коммерческий директор. Ошибка в одной цифре может задержать оплату на 3 недели."},
  {"type":"quote","text":"Бумага — лучший друг подрядчика. Без документов ты — никто","author":"Поговорка строителей"},
  {"type":"divider"}
]$blocks$::jsonb, 8, ARRAY['КС-2','КС-3','документооборот','акты','исполнительная'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','На основании какого документа производится оплата?','[{"text":"КС-2","is_correct":false},{"text":"КС-3","is_correct":true},{"text":"Акт скрытых работ","is_correct":false},{"text":"Фотоотчёт","is_correct":false}]','Оплата производится на основании подписанной КС-3 — справки о стоимости выполненных работ.'),
(lid,2,'choice','Какова средняя задержка оплаты при ошибках в КС-2?','[{"text":"7 дней","is_correct":false},{"text":"15 дней","is_correct":false},{"text":"23 дня","is_correct":true},{"text":"30 дней","is_correct":false}]','Средняя задержка оплаты по проектам с ошибками в КС-2 — 23 дня (vs 7 дней без ошибок).'),
(lid,3,'truefalse','Акты скрытых работ можно оформить после закрытия доступа к конструкции.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Акты скрытых работ оформляются в день выполнения. Задним числом — основание для отказа от приёмки.'),
(lid,4,'choice','Каков максимальный срок закрытия КС-2/КС-3 после завершения работ?','[{"text":"3 дня","is_correct":false},{"text":"5 дней","is_correct":true},{"text":"10 дней","is_correct":false},{"text":"14 дней","is_correct":false}]','KPI Асгарда — максимум 5 рабочих дней на закрытие документации.'),
(lid,5,'choice','Сколько раз нужно проверить КС-2 перед отправкой?','[{"text":"1 раз — сам РП","is_correct":false},{"text":"2 раза — РП и бухгалтер","is_correct":false},{"text":"3 раза — РП, бухгалтер, комдир","is_correct":true},{"text":"Не нужно проверять","is_correct":false}]','КС-2 проверяется трижды: сам РП, бухгалтер, коммерческий директор.'),
(lid,6,'scenario','КС-2 содержит ошибку в расценке. Заказчик вернул документ. Что делать?','[{"text":"Спорить с заказчиком","is_correct":false},{"text":"Исправить, перепроверить весь документ, отправить повторно","is_correct":true},{"text":"Подождать — может пропустят","is_correct":false},{"text":"Отправить КС-3 без исправления КС-2","is_correct":false}]','Исправить ошибку, перепроверить ВЕСЬ документ (часто ошибки не одиночные), отправить повторно с извинениями.');
END $$;

-- УРОКИ 9-12 (необязательные) — более короткие
-- УРОК 9: Техническая приёмка работ
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (10, 'pm', 'Техническая приёмка работ — чек-листы, дефектовка, ОТК', 'Искусство руководства', '🔧', '#1e2840', $blocks$[
  {"type":"cover","icon":"🔧","title":"Техническая приёмка работ","subtitle":"Чек-листы, дефектовка и контроль качества"},
  {"type":"intro","text":"Приёмка — момент истины. Всё, что вы делали на проекте, оценивается в одном моменте: заказчик смотрит результат и решает — принять или отправить на доработку. Подготовка к приёмке начинается не в последний день, а с первого дня работ."},
  {"type":"text_block","title":"Самоконтроль до приёмки заказчиком","text":"Перед вызовом представителя заказчика на приёмку РП и мастер проводят внутренний контроль. Визуальный осмотр каждого объекта работ, инструментальный контроль (замеры толщин, давления, чистоты), проверка документации. Все дефекты, обнаруженные при самоконтроле, устраняются ДО приёмки. Нет ничего хуже, чем заказчик, который нашёл дефект, который вы сами должны были заметить. Это удар по профессиональной репутации. В Асгарде действует правило: дефект, найденный при самоконтроле — урок. Дефект, найденный заказчиком — провал."},
  {"type":"steps","title":"Чек-лист самоконтроля перед приёмкой","items":["Визуальный осмотр: нет ли видимых дефектов, потёков, повреждений","Замеры: толщины изоляции, чистота поверхности, давление опрессовки","Документация: все акты, протоколы, фото собраны и подписаны","Площадка: убрана, отходы утилизированы, оборудование демонтировано","Скрытые работы: все акты подписаны до закрытия доступа","Сертификаты: на все материалы есть документы качества"]},
  {"type":"warning","level":"warning","text":"Дефект, найденный при самоконтроле — урок. Дефект, найденный заказчиком — провал. Проводите самоконтроль за 1-2 дня до приёмки, чтобы было время на устранение."},
  {"type":"stat","value":"1-2 дня","label":"запас времени между самоконтролем и приёмкой заказчиком","source":"Стандарт Асгарда"},
  {"type":"fact_card","icon":"✅","text":"Проекты, где РП провёл полный самоконтроль перед приёмкой, принимаются заказчиком с первого раза в 94% случаев. Без самоконтроля — только в 61%."},
  {"type":"highlight","text":"94% приёмок с первого раза — при полном самоконтроле. 61% — без него. Разница — ваша репутация."},
  {"type":"divider"}
]$blocks$::jsonb, 7, ARRAY['приёмка','ОТК','качество','дефекты','контроль'], false, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какой процент приёмок с первого раза при полном самоконтроле?','[{"text":"75%","is_correct":false},{"text":"85%","is_correct":false},{"text":"94%","is_correct":true},{"text":"99%","is_correct":false}]','При полном самоконтроле — 94% приёмок с первого раза.'),
(lid,2,'choice','За сколько дней до приёмки нужно провести самоконтроль?','[{"text":"В тот же день","is_correct":false},{"text":"За 1-2 дня","is_correct":true},{"text":"За 5 дней","is_correct":false},{"text":"За неделю","is_correct":false}]','Самоконтроль за 1-2 дня до приёмки — чтобы было время на устранение дефектов.'),
(lid,3,'truefalse','Дефект, найденный заказчиком при приёмке — это нормальная ситуация.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Дефект, найденный заказчиком — провал. Все дефекты должны быть выявлены при самоконтроле.'),
(lid,4,'choice','Какой процент приёмок с первого раза БЕЗ самоконтроля?','[{"text":"41%","is_correct":false},{"text":"51%","is_correct":false},{"text":"61%","is_correct":true},{"text":"71%","is_correct":false}]','Без самоконтроля только 61% приёмок проходят с первого раза.');
END $$;

-- УРОК 10: Организация строительной площадки
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (11, 'pm', 'Организация строительной площадки — логистика, склад, быт', 'Искусство руководства', '🏗️', '#1e3828', $blocks$[
  {"type":"cover","icon":"🏗️","title":"Организация площадки","subtitle":"Логистика, складирование и бытовые условия бригады"},
  {"type":"intro","text":"Хорошо организованная площадка — половина успеха проекта. Когда инструменты на месте, материалы под рукой, бытовка тёплая, а склад в порядке — бригада работает быстрее и качественнее. Хаос на площадке = потери времени, травмы, конфликты."},
  {"type":"text_block","title":"Организация рабочей зоны на НПЗ","text":"На промышленных объектах рабочая зона строго ограничена заказчиком. РП получает план территории с указанием разрешённых зон для размещения оборудования, складирования материалов и бытовок. Нарушение границ — штраф от заказчика и риск аварии. Перед началом работ проводится совместный обход с представителем заказчика: определяются маршруты движения, точки подключения электричества и воды, места установки предупреждающих знаков. Всё фиксируется в акте допуска на территорию."},
  {"type":"icon_grid","title":"Зоны на площадке","items":[{"icon":"🔧","label":"Рабочая зона","desc":"Непосредственно у объекта работ — ограждена лентой"},{"icon":"📦","label":"Склад","desc":"Хранение материалов и реагентов — навес, поддоны"},{"icon":"🏠","label":"Бытовка","desc":"Раздевалка, обогрев, приём пищи, хранение СИЗ"},{"icon":"🚛","label":"Площадка разгрузки","desc":"Для доставки оборудования и материалов"},{"icon":"♻️","label":"Площадка отходов","desc":"Контейнеры для промышленных и бытовых отходов"},{"icon":"🚿","label":"Санитарная зона","desc":"Мойка, душ, туалет — согласно СанПиН"}]},
  {"type":"warning","level":"danger","text":"Химические реагенты хранятся ТОЛЬКО в специально оборудованном месте с поддоном для сбора утечек. Нарушение правил хранения химии на НПЗ — немедленное удаление бригады с объекта и штраф до 500 тысяч рублей."},
  {"type":"stat","value":"500 тыс ₽","label":"штраф за нарушение правил хранения химии на НПЗ","source":"Типовой договор"},
  {"type":"highlight","text":"Порядок на площадке — это не просто эстетика. Это безопасность, скорость работы и отношение заказчика к вашей компании."},
  {"type":"divider"}
]$blocks$::jsonb, 7, ARRAY['площадка','логистика','склад','быт','НПЗ'], false, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Каков штраф за нарушение правил хранения химии на НПЗ?','[{"text":"50 тыс ₽","is_correct":false},{"text":"100 тыс ₽","is_correct":false},{"text":"500 тыс ₽","is_correct":true},{"text":"1 млн ₽","is_correct":false}]','Штраф за нарушение правил хранения химии на НПЗ — до 500 тысяч рублей.'),
(lid,2,'truefalse','Химические реагенты можно временно хранить прямо на земле рядом с рабочей зоной.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Реагенты хранятся ТОЛЬКО в специально оборудованном месте с поддоном для сбора утечек.'),
(lid,3,'choice','Что нужно сделать перед началом работ на территории заказчика?','[{"text":"Сразу начать работу","is_correct":false},{"text":"Совместный обход с представителем заказчика","is_correct":true},{"text":"Только получить пропуска","is_correct":false},{"text":"Позвонить главному инженеру","is_correct":false}]','Перед началом — совместный обход: маршруты, подключения, знаки. Всё фиксируется в акте допуска.');
END $$;

-- УРОК 11: CRM Асгарда для РП
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (12, 'pm', 'CRM Асгарда для РП — тендеры, работы, финансы, мессенджер', 'Искусство руководства', '📱', '#182840', $blocks$[
  {"type":"cover","icon":"📱","title":"CRM Асгарда для РП","subtitle":"Как использовать систему на максимум"},
  {"type":"intro","text":"CRM Асгарда — ваш главный рабочий инструмент. Тендеры, работы, бригады, финансы, документы, мессенджер — всё в одном месте. РП, который не ведёт CRM — работает вслепую. В этом свитке — обзор всех модулей, которые использует руководитель проекта ежедневно."},
  {"type":"text_block","title":"Модуль «Тендеры»","text":"Все входящие тендеры попадают в CRM автоматически. РП видит список доступных тендеров, может просмотреть ТЗ, загрузить документацию, создать КП через систему Мимир. Статусы тендера: Новый → В работе → Готово к отправке КП → Отправлен → Выиграли / Проиграли / Отменён. РП обязан обновлять статус в тот же день, когда меняется ситуация. По выигранным тендерам автоматически создаётся карточка «Работы» — следующий этап жизненного цикла."},
  {"type":"icon_grid","title":"Модули CRM для РП","items":[{"icon":"📋","label":"Тендеры","desc":"Входящие запросы, КП, статусы, документация"},{"icon":"🏗️","label":"Работы","desc":"Активные проекты: бригады, графики, прогресс, финансы"},{"icon":"👷","label":"Бригады","desc":"Состав, навыки, рейтинги, допуски каждого рабочего"},{"icon":"💰","label":"Финансы","desc":"Сметы, счета, акты, дебиторка, план/факт бюджета"},{"icon":"💬","label":"MAX-мессенджер","desc":"Чат с бригадой, заказчиком, офисом — в контексте проекта"},{"icon":"📊","label":"Аналитика","desc":"KPI, дашборды, отчёты — всё в реальном времени"}]},
  {"type":"steps","title":"Ежедневный ритуал РП в CRM","items":["Утро: проверить сообщения в MAX-мессенджере от бригад и заказчиков","Проверить фотоотчёты бригад — все ли загружены за вчерашний день","Обновить прогресс по каждому активному проекту (% выполнения)","Проверить бюджет: нет ли отклонений по расходам","Ответить на заявки от бригад: материалы, замены, проблемы","Проверить статусы тендеров: нет ли новых или требующих действий","Вечер: записать итоги дня, обновить риски, запланировать завтра"]},
  {"type":"highlight","text":"CRM — не отчётность для начальства. CRM — ваш рабочий стол. Чем больше данных вы вводите, тем больше система помогает: напоминания, аналитика, автоматические отчёты."},
  {"type":"stat","value":"7","label":"модулей CRM используют РП ежедневно","source":"Аналитика использования CRM"},
  {"type":"fact_card","icon":"📱","text":"РП, которые ведут CRM ежедневно, тратят на отчётность на 60% меньше времени, чем те, кто заполняет всё «задним числом» раз в неделю. Автоматические отчёты формируются за 30 секунд вместо 2 часов ручной работы."},
  {"type":"divider"}
]$blocks$::jsonb, 8, ARRAY['CRM','Мимир','тендеры','работы','мессенджер'], false, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','На сколько процентов меньше времени тратят на отчётность РП с ежедневным ведением CRM?','[{"text":"30%","is_correct":false},{"text":"45%","is_correct":false},{"text":"60%","is_correct":true},{"text":"80%","is_correct":false}]','РП с ежедневным ведением CRM тратят на отчётность на 60% меньше времени.'),
(lid,2,'choice','Сколько модулей CRM используют РП ежедневно?','[{"text":"3","is_correct":false},{"text":"5","is_correct":false},{"text":"7","is_correct":true},{"text":"10","is_correct":false}]','РП ежедневно используют 7 модулей CRM: тендеры, работы, бригады, финансы, мессенджер, аналитика, документы.'),
(lid,3,'truefalse','CRM можно заполнять раз в неделю — результат будет тот же.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Заполнение задним числом занимает на 60% больше времени и теряет точность данных.'),
(lid,4,'choice','За сколько секунд формируется автоматический отчёт в CRM?','[{"text":"5 секунд","is_correct":false},{"text":"30 секунд","is_correct":true},{"text":"5 минут","is_correct":false},{"text":"30 минут","is_correct":false}]','Автоматические отчёты формируются за 30 секунд вместо 2 часов ручной работы.');
END $$;

-- УРОК 12: Тайм-менеджмент РП
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (13, 'pm', 'Тайм-менеджмент РП — приоритизация, делегирование, фокус', 'Искусство руководства', '🎯', '#1e2040', $blocks$[
  {"type":"cover","icon":"🎯","title":"Тайм-менеджмент РП","subtitle":"Как управлять временем, когда всё горит одновременно"},
  {"type":"intro","text":"У руководителя проекта всегда больше задач, чем времени. 3-5 активных проектов, десятки звонков, сотни сообщений, документы, совещания — день пролетает мгновенно, а список дел только растёт. Тайм-менеджмент РП — это не про ежедневники и помидорную технику. Это про жёсткую приоритизацию и безжалостное делегирование."},
  {"type":"text_block","title":"Матрица Эйзенхауэра для РП","text":"Все задачи РП делятся на 4 квадранта. Квадрант 1 (срочно + важно): аварийные ситуации, горящие дедлайны, претензии заказчика — делай СЕЙЧАС. Квадрант 2 (важно + не срочно): планирование, обучение, профилактика рисков — планируй и делай регулярно. Квадрант 3 (срочно + не важно): большинство звонков, «срочных» запросов коллег — делегируй. Квадрант 4 (не срочно + не важно): бесполезные совещания, перфекционизм в мелочах — убирай. 80% времени РП должно уходить на квадранты 1 и 2. Если большая часть дня — квадрант 3, значит вы работаете на чужие приоритеты."},
  {"type":"warning","level":"warning","text":"Самая частая ловушка РП — «всё делать самому». Если вы тратите время на задачи, которые может выполнить мастер, бухгалтер или помощник — вы неэффективны. Делегируйте всё, что можно делегировать. Ваша задача — управлять, а не делать."},
  {"type":"steps","title":"Утренний ритуал РП (15 минут)","items":["Проверить CRM: есть ли красные статусы по проектам (2 мин)","Просмотреть сообщения: ответить на срочные, остальные — после 10:00 (3 мин)","Определить ТОП-3 задачи дня — что ОБЯЗАТЕЛЬНО нужно сделать сегодня (3 мин)","Проверить календарь: совещания, звонки, дедлайны (2 мин)","Делегировать: что из списка можно передать мастеру или помощнику (3 мин)","Начать с самой сложной задачи — пока энергия максимальна (2 мин на выбор)"]},
  {"type":"stat","value":"80%","label":"времени РП должно уходить на важные задачи (квадранты 1+2)","source":"Стандарт эффективности Асгарда"},
  {"type":"fact_card","icon":"⏱️","text":"Исследование McKinsey показало, что средний менеджер тратит 28% рабочего времени на email и мессенджеры, 19% на поиск информации и только 39% на продуктивную работу. В Асгарде CRM сокращает время на поиск информации до 5%, высвобождая 14% дня для реальной работы."},
  {"type":"highlight","text":"Правило ТОП-3: каждое утро определяй 3 главные задачи дня. Если ты выполнил ТОП-3 — день прошёл не зря, даже если остальные 20 задач подождут."},
  {"type":"quote","text":"Если ты не управляешь своим временем — им управляют другие","author":"Стивен Кови"},
  {"type":"divider"}
]$blocks$::jsonb, 7, ARRAY['время','приоритеты','делегирование','фокус','Эйзенхауэр'], false, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какой процент времени РП должен уходить на важные задачи (квадранты 1+2)?','[{"text":"50%","is_correct":false},{"text":"65%","is_correct":false},{"text":"80%","is_correct":true},{"text":"95%","is_correct":false}]','80% времени РП должно уходить на квадранты 1 и 2 матрицы Эйзенхауэра.'),
(lid,2,'choice','Сколько главных задач нужно определить каждое утро?','[{"text":"1","is_correct":false},{"text":"3","is_correct":true},{"text":"5","is_correct":false},{"text":"10","is_correct":false}]','Правило ТОП-3: каждое утро определяй 3 главные задачи дня.'),
(lid,3,'choice','Сколько процентов рабочего времени средний менеджер тратит на email по данным McKinsey?','[{"text":"12%","is_correct":false},{"text":"20%","is_correct":false},{"text":"28%","is_correct":true},{"text":"40%","is_correct":false}]','По данным McKinsey, средний менеджер тратит 28% рабочего времени на email и мессенджеры.'),
(lid,4,'truefalse','РП должен стараться всё делать сам — так надёжнее.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Делегируйте всё, что можно делегировать. Задача РП — управлять, а не делать.');
END $$;
